import { useEffect, useRef, type ReactNode } from 'react';
import { IconAlert } from '../../../icons/alert';
import { IconCheck } from '../../../icons/check';
import { announce } from '../../../primitives/announce';
import { useControllableState } from '../../../primitives/use-controllable-state';
import { useLatest } from '../../../primitives/use-latest';
import { Button, type ButtonProps } from '../button/Button';
import './loading-state-button.css';

export type LoadState = 'idle' | 'loading' | 'success' | 'error';

export interface LoadingStateButtonProps extends Omit<
  ButtonProps,
  'children' | 'onClick' | 'icon'
> {
  /** What the button says in each state. Use the same verb throughout: Save, Saving…, Saved. */
  labels: Record<LoadState, string>;
  /** The work to do. A returned promise drives the states; a rejection shows the error state. */
  onAction: () => unknown;
  /** Control the state yourself instead of letting the promise drive it. */
  state?: LoadState;
  onStateChange?: (state: LoadState) => void;
  /** Milliseconds before a success returns to idle. */
  resetAfter?: number;
  /** An icon for the idle state. */
  icon?: ReactNode;
}

function Spinner() {
  return (
    <svg
      className="atl-load__spinner"
      viewBox="0 0 20 20"
      width="20"
      height="20"
      aria-hidden="true"
    >
      <circle cx="10" cy="10" r="7" />
      <path d="M10 3a7 7 0 0 1 7 7" />
    </svg>
  );
}

/**
 * A button that shows its work: idle, then busy, then the outcome, without ever changing
 * width. Each state's label is announced, failures assertively.
 */
export function LoadingStateButton({
  labels,
  onAction,
  state: stateProp,
  onStateChange,
  resetAfter = 2400,
  icon,
  className,
  ...props
}: LoadingStateButtonProps) {
  const [state, setState] = useControllableState<LoadState>({
    value: stateProp,
    defaultValue: 'idle',
    onChange: onStateChange,
  });
  const latestLabels = useLatest(labels);
  const first = useRef(true);
  const alive = useRef(true);

  useEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
    };
  }, []);

  // Announce every state change after the first render.
  useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    if (state === 'idle') return;
    announce(latestLabels.current[state], state === 'error' ? 'assertive' : 'polite');
  }, [state, latestLabels]);

  useEffect(() => {
    if (state !== 'success') return;
    const timer = window.setTimeout(() => setState('idle'), resetAfter);
    return () => window.clearTimeout(timer);
  }, [state, resetAfter, setState]);

  const run = async () => {
    if (state === 'loading') return;
    setState('loading');
    try {
      await onAction();
      if (alive.current) setState('success');
    } catch {
      if (alive.current) setState('error');
    }
  };

  const faces: Array<[LoadState, ReactNode]> = [
    ['idle', icon],
    ['loading', <Spinner key="spinner" />],
    ['success', <IconCheck key="check" />],
    ['error', <IconAlert key="alert" />],
  ];

  return (
    <Button
      {...props}
      className={['atl-load', className].filter(Boolean).join(' ')}
      data-state={state}
      aria-busy={state === 'loading' || undefined}
      aria-disabled={state === 'loading' || props['aria-disabled'] === 'true' ? 'true' : undefined}
      onClick={() => {
        void run();
      }}
    >
      <span className="atl-load__stack">
        {faces.map(([face, faceIcon]) => (
          <span
            key={face}
            className="atl-load__face"
            data-active={face === state || undefined}
            // Hidden from assistive technology at once, even while it fades out visually.
            aria-hidden={face === state ? undefined : true}
          >
            {faceIcon ? (
              <span className="atl-load__icon" aria-hidden="true">
                {faceIcon}
              </span>
            ) : null}
            <span>{labels[face]}</span>
          </span>
        ))}
      </span>
    </Button>
  );
}

@layer atlas.components {
  /* Every face sits in the same grid cell, so the button keeps the width of its widest state. */
  .atl-load__stack {
    display: inline-grid;
  }

  .atl-load__face {
    grid-area: 1 / 1;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-xs);
    visibility: hidden;
    opacity: 0;
    translate: 0 4px;
    transition:
      opacity var(--dur-step) var(--ease-anchor),
      translate var(--dur-step) var(--ease-anchor),
      visibility 0s linear var(--dur-step);
  }

  .atl-load__face[data-active] {
    visibility: visible;
    opacity: 1;
    translate: 0 0;
    transition:
      opacity var(--dur-step) var(--ease-anchor),
      translate var(--dur-step) var(--ease-anchor),
      visibility 0s;
  }

  .atl-load__icon {
    display: grid;
    place-items: center;
  }

  .atl-load__icon svg {
    width: 1.15em;
    height: 1.15em;
  }

  /* While busy the button keeps its colours; aria-disabled must not grey it out. */
  .atl-load[data-state='loading'][aria-disabled='true'] {
    opacity: 1;
    cursor: progress;
  }

  .atl-load[data-state='success'] {
    --atl-button-bg: color-mix(in oklch, var(--starboard) 22%, var(--shoal));
    --atl-button-fg: var(--ink);
    --atl-button-edge: var(--starboard);
  }

  .atl-load[data-state='error'] {
    --atl-button-bg: color-mix(in oklch, var(--port) 18%, var(--shoal));
    --atl-button-fg: var(--ink);
    --atl-button-edge: var(--port);
  }

  .atl-load[data-state='success'] .atl-load__icon {
    color: var(--starboard);
  }

  .atl-load[data-state='error'] .atl-load__icon {
    color: var(--port);
  }

  .atl-load__spinner {
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    animation: atl-load-turn 900ms linear infinite;
  }

  .atl-load__face:not([data-active]) .atl-load__spinner {
    animation: none;
  }

  .atl-load__spinner circle {
    opacity: 0.3;
  }

  @keyframes atl-load-turn {
    to {
      rotate: 360deg;
    }
  }

  /* Reduced motion: no spinning. The label already says the work is in progress. */
  @media (prefers-reduced-motion: reduce) {
    :root:not([data-motion='full']) .atl-load__spinner {
      animation: none;
    }
  }

  :root[data-motion='reduce'] .atl-load__spinner {
    animation: none;
  }
}
